  "property_id": "PROP-0036",
  "title": "Verify Trust Boundary Integrity: Is ModExp gas calculation safe from integer overflow?",
  "severity": "Critical",
  "test_procedure": "1. Test with maximum possible base_length, modulus_length, exponent_length. 2. Calculate intermediate values (complexity * iterations). 3. Verify no overflow in 64-bit, 128-bit, or 256-bit arithmetic. 4. Check client source for appropriate integer types. 5. Test near-overflow values to trigger potential wrap-around.",
  "bug_class": "Integer Overflow"
}
CODE_EXCERPT: |
  // Reth delegates ModExp gas calculation to revm (external dependency).
  // In reth codebase, ModExp is referenced only as a precompile identifier:
  // crates/rpc/rpc-eth-api/src/helpers/config.rs:181
  //   PrecompileId::ModExp => "MODEXP",
  // The actual gas calculation logic is in revm's precompile implementation.
  // Reth uses revm as a dependency for all EVM execution including precompile gas.

PROPERTY_ASSERTION: "ModExp gas calculation must not overflow during intermediate arithmetic"
GRAPH_ELEMENT: "ModExp precompile gas calculation"
